*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --bg:           #0f1117;
  --surface:      #1a1d27;
  --surface-hover:#21253a;
  --border:       #2e3347;
  --accent:       #7c6af7;
  --accent-light: #a899ff;
  --text:         #e2e4f0;
  --text-muted:   #8b90a8;
  --answer-bg:    #13161f;
  --radius:       10px;
  --transition:   220ms ease;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: 'Segoe UI', system-ui, -apple-system, sans-serif;
  font-size: 1rem;
  line-height: 1.65;
  min-height: 100vh;
}

/* ── Skip link ────────────────────────────────────────────────── */
.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  background: var(--accent);
  color: #fff;
  padding: 0.5rem 1rem;
  border-radius: 0 0 var(--radius) var(--radius);
  font-weight: 600;
  text-decoration: none;
  z-index: 999;
  transition: top var(--transition);
}
.skip-link:focus { top: 0; }

/* ── Page layout ──────────────────────────────────────────────── */
header {
  text-align: center;
  padding: 3.5rem 1rem 2rem;
  border-bottom: 1px solid var(--border);
}

header .eyebrow {
  display: inline-block;
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--accent-light);
  margin-bottom: 0.75rem;
}

header h1 {
  font-size: clamp(1.75rem, 4vw, 2.75rem);
  font-weight: 800;
  color: #fff;
  letter-spacing: -0.02em;
  line-height: 1.2;
}

header p {
  margin-top: 0.75rem;
  color: var(--text-muted);
  font-size: 1.05rem;
  max-width: 42ch;
  margin-inline: auto;
}

main {
  max-width: 740px;
  margin-inline: auto;
  padding: 2.5rem 1rem 4rem;
}

/* ── FAQ list ─────────────────────────────────────────────────── */
#faq-list {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

/* ── Individual item (.example) ──────────────────────────────── */
.example {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  transition: border-color var(--transition);
}

.example:has([aria-expanded="true"]) {
  border-color: var(--accent);
}

/* ── Question button ──────────────────────────────────────────── */
.example h2 {
  /* remove UA heading margin; keep it a landmark */
  font-size: 1rem;
}

.example h2 button {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  width: 100%;
  background: transparent;
  border: none;
  color: var(--text);
  font-family: inherit;
  font-size: 1rem;
  font-weight: 600;
  line-height: 1.4;
  text-align: left;
  padding: 1.15rem 1.35rem;
  cursor: pointer;
  transition: background var(--transition), color var(--transition);
}

.example h2 button:hover,
.example h2 button:focus-visible {
  background: var(--surface-hover);
  color: var(--accent-light);
  outline: none;
}

.example h2 button:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: -2px;
  border-radius: calc(var(--radius) - 1px);
}

/* Chevron icon */
.example h2 button .chevron {
  flex-shrink: 0;
  width: 18px;
  height: 18px;
  color: var(--accent);
  transition: transform var(--transition);
}

.example h2 button[aria-expanded="true"] .chevron {
  transform: rotate(180deg);
}

/* ── Answer panel (.details) ──────────────────────────────────── */
.details {
  padding: 0 1.35rem 1.25rem;
  background: var(--answer-bg);
  border-top: 1px solid var(--border);
  color: var(--text-muted);
  font-size: 0.97rem;
  line-height: 1.7;
  /* animate open/close */
  animation: slideDown var(--transition) ease forwards;
}

.details p + p { margin-top: 0.75rem; }

@keyframes slideDown {
  from { opacity: 0; transform: translateY(-6px); }
  to   { opacity: 1; transform: translateY(0); }
}

/* ── Footer ───────────────────────────────────────────────────── */
footer {
  text-align: center;
  padding: 1.5rem;
  color: var(--text-muted);
  font-size: 0.85rem;
  border-top: 1px solid var(--border);
}

/* ── Forced colors (high-contrast mode) ──────────────────────── */
@media (forced-colors: active) {
  .example { border: 1px solid ButtonText; }
  .example h2 button { forced-color-adjust: auto; }
  .chevron { forced-color-adjust: auto; }
}

/* ── Reduced motion ───────────────────────────────────────────── */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { transition-duration: 0ms !important; animation-duration: 0ms !important; }
}

/* ── Narrow viewport reflow (320 px) ─────────────────────────── */
@media (max-width: 360px) {
  header { padding: 2rem 0.75rem 1.25rem; }
  main { padding: 1.5rem 0.75rem 3rem; }
  .example h2 button { padding: 1rem 1rem; }
  .details { padding: 0 1rem 1rem; }
}
