const FAQ_ITEMS = [
  {
    question: "Why do cats purr?",
    answer:
      "Cats purr for a range of reasons beyond simple contentment. They produce the sound by rapidly contracting and relaxing laryngeal muscles at 25–150 Hz. " +
      "Interestingly, cats also purr when stressed or injured — the vibration frequency may promote bone density and accelerate healing, making purring a built-in self-soothing mechanism.",
  },
  {
    question: "Why do cats knead?",
    answer:
      "Kneading — rhythmically pushing their paws against a soft surface — is rooted in kittenhood, where it stimulates milk flow from the mother. " +
      "Adult cats continue the behaviour as a comfort ritual. It also activates scent glands in their paw pads, leaving a subtle territorial mark on their favourite spots (and people).",
  },
  {
    question: "Do cats really have nine lives?",
    answer:
      "No — cats have one life, just like every other mammal. The myth likely arose from their remarkable ability to survive falls (the 'righting reflex' lets them orient mid-air) " +
      "and their cautious, self-preserving nature. Ancient cultures also associated the number nine with luck and longevity, which probably helped the legend stick.",
  },
  {
    question: "Why do cats bring dead animals home?",
    answer:
      "It's an instinct rooted in their nature as obligate carnivores and solitary hunters. Some behaviourists believe cats are 'teaching' their household companions to hunt, " +
      "or simply sharing a successful catch. For indoor cats with plenty of food, it's still a strong drive — redirecting it with puzzle feeders and active play can help.",
  },
  {
    question: "Why do cats sleep so much?",
    answer:
      "Cats are crepuscular hunters (most active at dawn and dusk) and conserve energy between hunts. An average cat sleeps 12–16 hours a day, and some seniors or indoor cats can reach 20. " +
      "Their sleep cycles include both light dozing — where they stay alert to sounds — and deep REM sleep where dreaming occurs.",
  },
  {
    question: "Can cats see in the dark?",
    answer:
      "Cats cannot see in complete darkness, but they see far better than humans in low light. Their eyes have a high rod-to-cone ratio, a wide pupil that opens very large, " +
      "and a reflective layer called the tapetum lucidum behind the retina that bounces light back for a second pass. That same layer is what causes the glowing 'eyeshine' in photos.",
  },
  {
    question: "Why do many cats dislike water?",
    answer:
      "Most domestic cats evolved from desert-dwelling ancestors who had little exposure to rain or bodies of water, so the sensation is unfamiliar. A wet coat also becomes heavy and harder " +
      "to groom, which makes cats feel vulnerable. That said, some breeds — Turkish Van, Maine Coon, Bengal — are notably water-tolerant, and individual cats vary widely.",
  },
  {
    question: "How long do cats typically live?",
    answer:
      "Indoor cats average 12–18 years; many reach their 20s with good care. The oldest cat on record, Creme Puff, lived to 38. " +
      "Outdoor cats face more hazards and average 2–5 years. Key longevity factors include diet, spaying/neutering, regular vet visits, and keeping them indoors or in a safe enclosure.",
  },
  {
    question: "Why do cats meow at humans but not at each other?",
    answer:
      "Adult cats almost never meow at other cats; they communicate with body language, scent, chirps, and trills instead. Researchers believe cats developed the meow specifically " +
      "as a communication tool directed at humans — essentially adapting infant-like vocalisations because they found it effective at getting food, attention, and door-opening services.",
  },
  {
    question: "Are cats truly solitary animals?",
    answer:
      "Wildcats are generally solitary hunters, but domestic cats are far more social than their reputation suggests. Feral colonies form around reliable food sources, with females often " +
      "raising kittens communally. Domestic cats frequently bond deeply with humans and other cats. Socialisation in the first 2–7 weeks of life has the biggest influence on adult temperament.",
  },
];

// ── Component functions (React-style) ─────────────────────────────────────────

/**
 * Renders the SVG chevron icon used in each trigger button.
 */
function ChevronIcon() {
  return `
    <svg class="chevron" viewBox="0 0 24 24" aria-hidden="true" focusable="false">
      <polyline points="6 9 12 15 18 9" fill="none" stroke="currentColor"
                stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/>
    </svg>
  `;
}

/**
 * Renders a single FAQ disclosure item.
 * @param {{ question: string, answer: string, index: number }} props
 */
function FAQItem({ question, answer, index }) {
  const id = `faq-panel-${index}`;
  return `
    <li>
      <div class="example">
        <h2>
          <button type="button" aria-expanded="true" aria-controls="${id}">
            ${escapeHTML(question)}
            ${ChevronIcon()}
          </button>
        </h2>
        <div class="details" id="${id}">
          <p>${escapeHTML(answer)}</p>
        </div>
      </div>
    </li>
  `;
}

/**
 * Renders the full FAQ list into a container element.
 * @param {{ items: typeof FAQ_ITEMS, container: HTMLElement }} props
 */
function FAQList({ items, container }) {
  container.innerHTML = items
    .map((item, index) => FAQItem({ ...item, index }))
    .join("");
}

// ── Behaviour ─────────────────────────────────────────────────────────────────

/**
 * Initialises disclosure behaviour on all rendered FAQ items.
 * Panels are collapsed via JS (not in HTML) so content remains visible
 * in reader mode and no-JS environments.
 */
function initDisclosures() {
  document.querySelectorAll(".example [aria-expanded]").forEach((btn) => {
    const panel = document.getElementById(btn.getAttribute("aria-controls"));
    if (!panel) return;

    // Collapse on init — content visible without JS
    btn.setAttribute("aria-expanded", "false");
    panel.hidden = true;

    btn.addEventListener("click", () => {
      const isOpen = btn.getAttribute("aria-expanded") === "true";
      btn.setAttribute("aria-expanded", String(!isOpen));
      panel.hidden = isOpen;
    });

    // Escape collapses an open panel and keeps focus on trigger
    btn.addEventListener("keydown", (e) => {
      if (e.key === "Escape" && btn.getAttribute("aria-expanded") === "true") {
        btn.setAttribute("aria-expanded", "false");
        panel.hidden = true;
      }
    });
  });
}

// ── Utilities ─────────────────────────────────────────────────────────────────

function escapeHTML(str) {
  return str
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

// ── Mount ─────────────────────────────────────────────────────────────────────

document.addEventListener("DOMContentLoaded", () => {
  const container = document.getElementById("faq-list");
  FAQList({ items: FAQ_ITEMS, container });
  initDisclosures();
});
