  return "<li><div class=\"example\"><h2><button type=\"button\" aria-expanded=\"true\" aria-controls=\"" + id + "\">" + escapeHTML(question) + ChevronIcon() + "</button></h2><div class=\"details\" id=\"" + id + "\"><p>" + escapeHTML(answer) + "</p></div></div></li>";
}

function FAQList({ items, container }) {
  container.innerHTML = items.map(function(item, index) { return FAQItem({ question: item.question, answer: item.answer, index: index }); }).join("");
}

function initDisclosures() {
  document.querySelectorAll(".example [aria-expanded]").forEach(function(btn) {
    var panel = document.getElementById(btn.getAttribute("aria-controls"));
    if (!panel) return;
    btn.setAttribute("aria-expanded", "false");
    panel.hidden = true;
    btn.addEventListener("click", function() {
      var isOpen = btn.getAttribute("aria-expanded") === "true";
      btn.setAttribute("aria-expanded", String(!isOpen));
      panel.hidden = isOpen;
    });
    btn.addEventListener("keydown", function(e) {
      if (e.key === "Escape" && btn.getAttribute("aria-expanded") === "true") {
        btn.setAttribute("aria-expanded", "false");
        panel.hidden = true;
      }
    });
  });
}

